with engine_sync.connect() as conn:
    # 1. Atualizar TOPs e valores
    for p in pedidos:
        conn.execute(text(
            "UPDATE orders SET order_type=:ot, total_value=:tv WHERE external_id=:eid"
        ), {"ot": p['order_type'], "tv": p['total_value'], "eid": p['external_id']})

    # 2. Inserir itens (id INTEGER - autoincrement, sem passar id)
    total_itens = 0
    for ext_id, items in itens.items():
        row = conn.execute(text(
            "SELECT codparc FROM orders WHERE external_id=:eid"
        ), {"eid": ext_id}).fetchone()
        if not row or not row[0]: continue
        codparc = int(row[0])
        conn.execute(text("DELETE FROM order_items WHERE codparc=:cp"), {"cp": codparc})
        for item in items:
            conn.execute(text("""
                INSERT INTO order_items (codparc, top_app, item_tipo, item_nome, peso_unit, qtd, dt_neg)
                VALUES (:cp, :top, :tipo, :nome, :peso, :qtd, :dt)
            """), {
                "cp": codparc,
                "top": str(item['top_app']),
                "tipo": str(item['cod']),
                "nome": str(item['nome']),
                "peso": float(item['peso_unit']),
                "qtd": int(item['qtd']),
                "dt": "2026-05-08",
            })
            total_itens += 1

    conn.commit()
    print(f"OK! {total_itens} itens inseridos!")

    r = conn.execute(text("SELECT order_type, COUNT(*) FROM orders WHERE status=\'pending\' GROUP BY order_type"))
    labels = {'1000':'Venda','1009':'Troca','1007':'Bonif.','1010':'Pre-ped.'}
    for row in r:
        print(f"  {labels.get(row[0], row[0])}: {row[1]} pedidos")
